# protocol-7 module: coding.helper.enforce_quota
# Enforces per-job byte quotas from config, defaulting to 4096 bytes

use strict;
use warnings;
use protocol7 qw(:config :log);

package Coding::Helper::EnforceQuota;

sub import {
    shift;
    no strict 'refs';
    *{'Coding::Helper::enforce_quota'} = \&enforce_quota;
    goto &import;
}

sub enforce_quota {
    my ($job, $usage) = @_;

    # Get the quota from config, default 4096 bytes
    my $quota = config_get('coding.helper.enforce_quota.quota', 4096);

    # Check if usage exceeds quota
    if ($usage > $quota) {
        log_warn(
            "Job '%s' has consumed %d bytes, exceeding quota of %d bytes",
            $job, $usage, $quota
        );
        return 0;
    }

    return 1;
}

1;
```

This module:

- **Reads the quota** from config using `config_get` with the key `coding.helper.enforce_quota.quota`, defaulting to `4096` bytes.
- **Logs a warning** via protocol-7's logging system when a job's byte usage exceeds its quota.
- **Returns `FALSE`** (0) when the quota is exceeded, and `TRUE` (1) otherwise.
